import backtrader as bt


class TripleSmaStrategy(bt.Strategy):
    params = (
        ("p_fast", 5),
        ("p_med", 20),
        ("p_slow", 50),
        ("stop_pct", 0.02),
    )

    def __init__(self):
        self.sma5 = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.p_fast
        )
        self.sma20 = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.p_med
        )
        self.sma50 = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.p_slow
        )
        self.crossover = bt.indicators.CrossOver(self.sma5, self.sma20)
        self.order = None

    def notify_order(self, order):
        if order.status in [
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ]:
            self.order = None

    def next(self):
        if self.order:
            return

        if self.position.size > 0:
            stop_price = self.position.price * (1.0 - self.p.stop_pct)
            if self.crossover[0] == -1 or self.data.close[0] <= stop_price:
                self.order = self.close()
        elif self.position.size < 0:
            stop_price = self.position.price * (1.0 + self.p.stop_pct)
            if self.crossover[0] == 1 or self.data.close[0] >= stop_price:
                self.order = self.close()
        else:
            if self.sma5[0] > self.sma20[0] > self.sma50[0]:
                cash = self.broker.getcash()
                size = int(cash / (self.data.close[0] * 1.001))
                if size > 0:
                    self.order = self.buy(size=size)
            elif self.sma5[0] < self.sma20[0] < self.sma50[0]:
                cash = self.broker.getcash()
                size = int(cash / (self.data.close[0] * 1.001))
                if size > 0:
                    self.order = self.sell(size=size)
